// GATE_DISCOVERY_TOKEN: a short stable substring of the discovery find clause (the `-name '*.test.sh'`
// neighborhood), declared once in resolveGate's own module scope and used BOTH to build the discovery
// string AND as the idempotence detector — so composer and detector cannot drift from each other by
// construction. The inline workflow-template.js mirror duplicates the same pairing.
const GATE_DISCOVERY_TOKEN = `-name '*.test.sh'`
// Self-discovering multi-runner gate (F12), IDEMPOTENT (engine-owned composition, ADR 0036).
// Given the declared base command (e.g. `node --test 'skills/**/*.test.mjs'`), returns
// a portable shell string that runs the declared gate AND discovers + runs every *.test.sh
// found in the repo tree (excluding node_modules, .git, and .claude). The bash suites are
// sorted and executed in order; any non-zero exit aborts immediately (|| exit 1).
// The .claude/ exclusion keeps a repo-root gate run from executing the ~100 stale duplicate
// suites under .claude/worktrees/ (WAR's own task worktrees).
// COUPLING (D9, #1372/#1343): the `|| exit 1` abort is load-bearing beyond gate semantics — a red
// bash suite stops the discovery loop, so suites after the abort point print no per-file banner and
// the captured gate log's bash half is truncated. The gate-audit seat prompts' truncation clause
// (mappedTestsLine/authMappedLine in workflow-template.js, plus the agents/war-auditor.md D7 bullet)
// depends on exactly this fail-fast shape to read a post-abort zero-hit grep as soft
// cannot-confirm rather than a provably-unrun hold. Change one, revisit the other.
// Empty/null/falsy declaredGate → the discovery clause ALONE (no leading &&).
// IDEMPOTENT: a declaredGate that ALREADY carries the discovery clause (detected via
// GATE_DISCOVERY_TOKEN) is returned UNCHANGED, so resolveGate(resolveGate(g)) === resolveGate(g).
// The engine now normalizes plan.gate through this composition AND the Lead still pre-resolves via
// --resolve-gate; idempotence makes that double composition harmless by construction (belt-and-suspenders).
// MIRRORED inline in workflow-template.js. Keep in sync.
export function resolveGate(declaredGate) {
  const discovery = [
    `for f in $(find . -type f ${GATE_DISCOVERY_TOKEN} -not -path '*/node_modules/*' -not -path '*/.git/*' -not -path '*/.claude/*' | sort);`,
    `do printf '\\n== gate(bash): %s ==\\n' "$f" && bash "$f" || exit 1; done`,
  ].join(' ')
  if (!declaredGate) return discovery
  if (declaredGate.includes(GATE_DISCOVERY_TOKEN)) return declaredGate
  return `${declaredGate} && ${discovery}`
}

// --- CLI ---------------------------------------------------------------------
// node war-config.mjs --preset <name>            -> print a filled preset config (stdout)
// node war-config.mjs --resolve-gate <cmd>       -> print the self-discovering gate string
// node war-config.mjs <path>   [--fill-defaults] -> validate a file; print filled config or "valid"
// node war-config.mjs --stdin  [--fill-defaults] -> validate JSON from stdin; same output
// exit 0 = valid; exit 1 = invalid (errors on stderr) or usage error
async function main(argv) {
  const args = argv.slice(2)
  const has = f => args.includes(f)
  const valOf = f => { const i = args.indexOf(f); return i >= 0 ? args[i + 1] : undefined }

  if (has('--help') || args.length === 0) {
    process.stdout.write('usage: war-config.mjs (--preset <name> | <path> | --stdin | --resolve-gate <cmd>) [--fill-defaults]\n')
    process.exit(args.length === 0 ? 1 : 0)
  }

  if (has('--resolve-gate')) {
    const cmd = valOf('--resolve-gate') ?? ''
    process.stdout.write(resolveGate(cmd) + '\n')
    process.exit(0)
  }

  if (has('--preset')) {
    try { process.stdout.write(JSON.stringify(presetConfig(valOf('--preset')), null, 2) + '\n'); process.exit(0) }

  // binary silently no-ops. Only an explicit `false` disables; absent, null, or unreadable mean on.
  // hooks.valeStyle: profile selector for the vale-md hook, one of VALE_STYLES. Default
  // 'workAuditRefine' — the repo's own fork (house rules + a tuned cut of Google);
  // 'google' is raw upstream Google; the other vendored styles ship in
  // hooks/vale-md/styles/; 'custom' reads the project-side
  // .claude/war/vale/.vale.ini written by the /war-room interview (fail-open to the
  // default when absent). Subordinate to valeMarkdown: when that is false, nothing runs.
  hooks: { replyStandard: true, valeMarkdown: true, valeStyle: 'workAuditRefine' },
  // overrides.testPattern: the run's declared test-floor glob set (space-separated glob tokens) | null.
  // null ⇒ today's hardcoded gate-mirror floor defaults, byte-identical. Floor ⊆ gate is ONE Setup
  // decision (ADR 0006): testPattern is pinned TOGETHER with the gate — though that confirmation is not
  // the final word on the VALUE under --afk, where a sanity-floor-rejected proposal is re-checked at each
  // phase launch and can be adopted monotonically (Lead-side, no write-back — this field is unchanged).
  // The floor always unions the gate's unconditional *.test.sh discovery — so no custom pattern can make
  // the floor exceed the gate.
  // overrides.ghUser: the personal `gh` account gh-preflight.sh asserts is active before every gh write
  // batch (multi-account machines) | null. Ships null — no real handle in any committed file (C1); it lives
  // in the local .claude/war/config.json. Validated as string|null by the generic overrides loop below.
  overrides: { gate: null, workingBranch: null, landingBranch: null, learningsTarget: null, testPattern: null, ghUser: null },
}

// Presets are partials, deep-merged over DEFAULTS by presetConfig().
export const PRESETS = {
  balanced: { profile: 'balanced' },
  thorough: {
    profile: 'thorough',
    agents: {
      // The worker tiers (base, docs, fix) inherit DEFAULTS. Every seat pinned below carries its
      // own value; the refiner pin sits one effort tier above the DEFAULTS refiner.
      auditor:  { model: 'fable',  effort: 'default' },
      refiner:  { model: 'sonnet', effort: 'xhigh' },
=== 315-350 ===

  // Overrides: known keys only (a courtesy error on typos like `testPatern` — the memory.* precedent,
  // so a mistyped key never silently runs the bare floor), each null or a string. testPattern carries two
  // extra checks. (1) glob-safe charset: its value is embedded single-quoted into an agent-executed shell
  // line (assert-test-in-diff.sh --pattern), so any char outside [A-Za-z0-9_.*?/[] -] — notably a quote,
  // ';', backtick, '$', or newline — could break out of the quoting, and an empty string is not usable.
  // (2) per space-separated token, a glob-SHAPE check against two forms that mis-match under the floor's
  // `case`-fnmatch: a `**/` token (fnmatch `*` already crosses `/`, so `**/` is not recursive descent — the
  // depth-agnostic form is a bare `*.ext` suffix; prefix conventions use the `pre_* */pre_*` root+nested
  // pair, per the case-glob-star lesson) and a `*<word>*` substring shape whose word is unbounded by `.`/`/`
  // (`*test_*` over-matches `latest_results.py`; anchor as `test_*.py` or `*/test_*.py`). Shape checks run
  // only on the clean charset — they are correctness footguns, not injection.
  const KNOWN_OVERRIDES = ['gate', 'workingBranch', 'landingBranch', 'learningsTarget', 'testPattern', 'ghUser']
  const GLOB_UNSAFE = /[^A-Za-z0-9_.*?\/ \[\]-]/
  // Non-object guard mirrors the memory.* block above: a hand-edited `overrides: null`/`overrides: 'x'`
  // would otherwise throw a raw TypeError at Object.keys() instead of a named validation error.
  if (!isObj(c.overrides)) { errors.push('overrides must be an object') }
  else for (const k of Object.keys(c.overrides)) {
    const v = c.overrides[k]
    if (!KNOWN_OVERRIDES.includes(k)) { errors.push(`overrides.${k} is not a known key (${KNOWN_OVERRIDES.join('|')}) — run /war-room to regenerate the config`); continue }
    if (v !== null && typeof v !== 'string') { errors.push(`overrides.${k} must be null or a string`); continue }
    if (k === 'testPattern' && typeof v === 'string') {
      if (v === '' || GLOB_UNSAFE.test(v))
        errors.push(`overrides.testPattern must be a non-empty glob-safe string (only [A-Za-z0-9_.*?/[] -]; no quotes, ';', backticks, '$', or newlines) — it is embedded into an agent-executed shell command`)
      else for (const tok of v.split(/\s+/).filter(Boolean)) {
        if (tok.includes('**/'))
          errors.push(`overrides.testPattern token '${tok}' contains '**/', which mis-globs under the floor's case-fnmatch ('*' already crosses '/') — use a bare '*.ext' suffix for depth-agnostic match, or the 'pre_* */pre_*' root+nested pair for a prefix convention`)
        else if (/\*[A-Za-z0-9_]+\*/.test(tok))
          errors.push(`overrides.testPattern token '${tok}' is a '*word*' substring shape that over-matches (e.g. '*test_*' also matches 'latest_results.py') — bound the word with '.'/'/' (e.g. 'test_*.py' or '*/test_*.py')`)
      }
    }
  }
  return { valid: errors.length === 0, errors }
}

// Spawn opts for a role: model always; effort only when non-default (omitted = inherit session).

// it and that existing case stays green unmodified. Exhausted path — RETHROW, never return null: a
// second death (or the redundant-guard death) throws a descriptive Error, so the Workflow pipeline()
// nulls the whole item and BOTH sites (probe AND confirm) converge on the existing Layer-4 retry →
// { probe, dropped:true } marker → gate INCOMPLETE path. Returning null here would let a null confirm
// fall through `if (c && c.reproduced === false)` below and silently stand an unconfirmed fail as a
// blocker (see the plan's Notes / conscious deviations).
// Trace stamps (result-spread ONLY, never a dispatch-opts key): the RETURNED result of a successful
// analyzed dispatch is spread with `dispatchedOn: <effective type>`, plus `fallbackEngaged: true`
// whenever it ran on ANALYZED_AGENT_FALLBACK while the preferred type ≠ the fallback (covers both the
// re-dispatch recovery and the pinned entry-swap successes; excludes the preferred===fallback
// override, where general-purpose IS the preferred and carries no fallbackEngaged key). Executed
// results are never stamped. Confirm-site stamps are consumed inside confirmStage and do not survive
// into probeResults (accepted residual; confirm engagement stays visible via the log token).
// Bound: a both-dead analyzed probe is preferred + fallback on the first pipeline pass, then
// pinned-fallback + redundant-guard rethrow on the Layer-4 retry — 3 dispatches, not 4 (only 2 for any
// slot dispatched AFTER the pin; in a preferred===fallback run the pin is never set). Composes with
// Layer 4, never multiplies it. Transient-death-pinning residual (accepted, NO unpin logic): one flaky
// preferred dispatch pins the rest of the run onto the fallback — fine, because confinement is
// type-independent (the scope-lock preamble + assert-no-repo-escape.sh ride every probe/confirm
// unconditionally) and the pin is run-scoped by construction (this scaffold body re-evaluates per
// Workflow run, which also discharges the no-cross-run-persistence non-goal). Pin race:
// `analyzedFallbackPinned` is a plain boolean set idempotently under JS's single-threaded microtask
// model — no torn state; under a concurrent pipeline several in-flight preferred dispatches may die
// before the first observer pins, so dead preferred dispatches are "at most the in-flight window",
// never exactly one.
let analyzedFallbackPinned = false
// Trace-stamp a returned result with the effective dispatch type; fallbackEngaged rides only when the
// result was produced on the fallback while the preferred type differs (uniform forensics across the
// re-dispatch recovery and pinned entry-swap successes; the override preferred===fallback case is a
// plain preferred success). Result-spread ONLY — never touches dispatch opts.
const stampResult = (r, dispatchedOn) =>
  (dispatchedOn === ANALYZED_AGENT_FALLBACK && ANALYZED_AGENT !== ANALYZED_AGENT_FALLBACK)
    ? { ...r, dispatchedOn, fallbackEngaged: true }
    : { ...r, dispatchedOn }
const dispatchAgent = async (prompt, opts = {}) => {
  if (opts.agentType === undefined) return agent(prompt, opts)   // executed probes — never wrapped, never stamped
  if (analyzedFallbackPinned) opts = { ...opts, agentType: ANALYZED_AGENT_FALLBACK }   // sticky entry swap — one place feeds guard/log/errors/stamps
  const label = opts.label || 'analyzed probe'
  try {
    const r = await agent(prompt, opts)
    if (r != null) return stampResult(r, opts.agentType)          // preferred/effective type answered
  } catch { /* dead dispatch — fall through to the fallback */ }
  if (opts.agentType === ANALYZED_AGENT_FALLBACK) {               // redundant-dispatch guard
    throw new Error(`red-team: analyzed dispatch for ${label} died on ${opts.agentType} (already the ${ANALYZED_AGENT_FALLBACK} fallback) — dropping the probe (gate → INCOMPLETE).`)
  }
  analyzedFallbackPinned = true                                  // sticky pin — first dead preferred dispatch pins the run (past the redundant guard, so a preferred===fallback run never reaches it)
  log(`analyzed-agent fallback engaged: ${label} — ${opts.agentType} dispatch died; re-dispatching with ${ANALYZED_AGENT_FALLBACK}.`)
  try {
    const r2 = await agent(prompt, { ...opts, agentType: ANALYZED_AGENT_FALLBACK })
    if (r2 != null) return stampResult(r2, ANALYZED_AGENT_FALLBACK)  // fallback recovered the probe
  } catch { /* both types dead — fall through to the loud rethrow */ }
  throw new Error(`red-team: analyzed dispatch for ${label} died on both ${opts.agentType} and ${ANALYZED_AGENT_FALLBACK} — dropping the probe (gate → INCOMPLETE).`)
}

// Probe (stage 1) + adversarial-confirm (stage 2) as named stages so a dropped probe can be retried.
// futureWorkRule rides alongside scopeLock on EVERY probe (analyzed AND executed) — the technique
// argument selects the presence-check (analyzed) vs future-work-vs-defect (executed) wording variant.
const runProbe = (p) => dispatchAgent(
  `${scopeLock(p.technique)}\n\n${futureWorkRule(p.technique, artifactKind)}\n\n${p.prompt}\n\nReturn ONLY the FINDINGS object (probe="${p.name}", kind="${p.kind}", technique="${p.technique}"). Prove any failure with reproduced evidence; never assert. Set needsDecision:true on any finding that is an ambiguity with more than one non-equivalent resolution — a hole only the user can settle. Only record a finding for an actual problem — a false claim, a gap, or an ambiguity (needsDecision). If a claim checks out, do NOT record it. A fully-clean probe returns status:"pass" with findings:[].`,
  { ...modelOpts, label: `probe:${p.name}`, phase: 'Probe',
    agentType: p.technique === 'analyzed' ? ANALYZED_AGENT : undefined, schema: FINDINGS })

const confirmStage = async (res, p) => {               // adversarial-confirm: refute any reproducible blocker
  const blocking = res && (res.findings || []).some(f => f.severity === 'Critical' || f.severity === 'Major')
  if (!res || (res.status !== 'fail' && !blocking)) return res
  const c = await dispatchAgent(
    `${scopeLock(p.technique)}\n\n`
    + `Independently try to REFUTE this red-team finding — reproduce it or disprove it. `
    + `Apply the self-confound gate to the probe itself: rule out the probe's own provision commands, sandbox reuse, or an earlier probe's mutation as the cause before the fail stands. `
    + `Work ONLY in a throwaway sandbox; never touch ${repo}.\nProbe: ${p.name}\nPlan: ${planFile}\n`
    + `Findings: ${JSON.stringify(res.findings)}`,
    { ...modelOpts, label: `${ADVERSARIAL_CONFIRM}:${p.name}`, phase: 'Confirm',
      agentType: p.technique === 'analyzed' ? ANALYZED_AGENT : undefined, schema: CONFIRM })
  if (c && c.reproduced === false) {
    return { ...res, status: 'warn',
      findings: (res.findings || []).map(f => ({ ...f, severity: 'Minor',
        reality: `${f.reality || ''} [unreproduced — downgraded by ${ADVERSARIAL_CONFIRM}: ${c.note || ''}]` })) }
  }
  return res
}

const results = await pipeline(allProbes, runProbe, confirmStage)

// Layer 4 — never silently drop a dead probe. A null = the agent died after the harness's own
// retries (or was skipped). Retry it ONCE; if it still dies, emit a { probe, dropped:true } marker
// so the gate counts the coverage gap and refuses to return CLEARED on a thinner run.
const probeResults = []
for (let i = 0; i < allProbes.length; i++) {
  let r = results[i]
  if (!r) {
    log(`Probe ${allProbes[i].name} returned no result — retrying once.`)
    const retried = await pipeline([allProbes[i]], runProbe, confirmStage)
    r = retried[0]
  }
  // Provenance strip (ADR 0043): the `adjudicated` stamp is Lead-applied post-run only, in the
  // Lead's working copy of the gate input — a probe has no legitimate path to it, so the key is
  // deleted from every finding of every collected result at this single site right before the push
  // (first-pass and retried results alike). One key only: findings without it pass by reference,
  // the dropped:true markers and the confirm-stage reality suffix (a declared key) are untouched.
  if (r && Array.isArray(r.findings)) {
    r = { ...r, findings: r.findings.map(f => {
      if (!f || typeof f !== 'object' || !('adjudicated' in f)) return f
      const { adjudicated, ...keep } = f
      return keep
    }) }
  }
  probeResults.push(r || { probe: allProbes[i].name, dropped: true })
}
const dropped = probeResults.filter(r => r && r.dropped).map(r => r.probe)
if (dropped.length) log(`⚠ coverage gap: ${dropped.length}/${allProbes.length} probe(s) dropped after retry — ${dropped.join(', ')}. The gate will return INCOMPLETE.`)

